static int r8152_mmd_read(struct r8152 *tp, u16 dev, u16 reg, u16 *data)
{
	int ret;

	ret = r8152_mmd_indirect(tp, dev, reg);
	if (ret < 0)
		goto out;
	ret = ocp_reg_read(tp, OCP_EEE_DATA, data);
	if (ret < 0)
		goto out;
	ret = ocp_reg_write(tp, OCP_EEE_AR, 0x0000);

out:
	return ret;
}
